import { readFileSync } from "node:fs";

import { expect, test as base, type APIRequestContext } from "@playwright/test";

import { sample, test, uniqueName } from "../../fixtures";

interface QueueItem {
  vendor_id: string;
  lowest_confidence: number;
}

async function createSubmittedVendor(member: APIRequestContext, name: string, insuranceFile: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "software", contact_email: "ops@harborline.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const uploads: [string, string][] = [
    ["w9", "w9.txt"],
    ["insurance_certificate", insuranceFile],
    ["contract", "contract.txt"],
  ];
  for (const [kind, file] of uploads) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
  }

  // Extraction runs in the background after each upload.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  return vendor.id;
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const unparsedId = await createSubmittedVendor(member, uniqueName("Unparsed Expiry"), "insurance_certificate_unparseable.txt");
  const parsedId = await createSubmittedVendor(member, uniqueName("Parsed Expiry"), "insurance_certificate.txt");

  const fetchQueue = async (): Promise<QueueItem[]> => {
    const res = await reviewer.get("/api/review-queue");
    expect(res.status(), await res.text()).toBe(200);
    return (await res.json()) as QueueItem[];
  };

  // Wait until both submitted vendors appear in the queue.
  await expect
    .poll(
      async () => {
        const ids = (await fetchQueue()).map((i) => i.vendor_id);
        return ids.includes(unparsedId) && ids.includes(parsedId);
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  // Act
  const queue = await fetchQueue();

  // Assert
  const unparsedIndex = queue.findIndex((i) => i.vendor_id === unparsedId);
  const parsedIndex = queue.findIndex((i) => i.vendor_id === parsedId);
  expect(unparsedIndex, "unparsed-date vendor is in the queue").toBeGreaterThanOrEqual(0);
  expect(parsedIndex, "parsed-date vendor is in the queue").toBeGreaterThanOrEqual(0);
  expect(unparsedIndex, "unparsed-date vendor is listed before the other").toBeLessThan(parsedIndex);

  const scores = queue.map((i) => i.lowest_confidence);
  expect(scores, "queue is ordered by lowest_confidence ascending").toEqual([...scores].sort((a, b) => a - b));
});
